```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <regex>

// Mapa de conversión de Markdown a HTML
const std::unordered_map<std::string, std::string> md2html = {
    {"# ", "<h1>"},
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"`", "<code>"},
    {"**", "<strong>"},
    {"__", "<strong>"},
    {"* ", "<em>"},
    {"_ ", "<em>"},
    {"[", "<a href="},
    {"](", ")</a>"},
    {"( ", "<a href="},
    {")", "</a>"},
    {"\\ ", "&nbsp;"},
    {"---", "<hr>"},
    {"---", "<hr>"},
    {"---", "<hr>"},
    {"** ", "<ul><li>"},
    {"* ", "<ul><li>"},
    {"", "</ul></li></ul>"},
    {"{ ", "<blockquote>"},
    {"} ", "</blockquote>"},
    {"> ", "<p>"},
    {"> ", "</p><p>"},
    {"", "</p>"}
};

// Función para convertir texto Markdown a HTML
std::string md2html(std::string& md_text) {
    std::string html_text;

    // Reemplazar las etiquetas de formato
    for (const auto& [md, html] : md2html) {
        std::regex expr(md);
        html_text.replace_all(md_text, html);
        md_text = std::regex_replace(md_text, expr, html);
    }

    return html_text;
}

int main() {
    std::string markdown = "## H1\n"
                           "### H2\n"
                           "#### H3\n"
                           "\n"
                           "Texto con **negritas** y *cursivas*.\n"
                           "\n"
                           "Enlace: [Google](https://www.google.com/).\n"
                           "\n"
                           "Código: `int main() { ... }`.\n"
                           "\n"
                           "Listado:\n"
