Aquí te presento un ejemplo de cómo leer un archivo de texto línea por línea en C++ y contar el número de apariciones de una palabra específica en el archivo:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string wordToCount; // palabra a contar
    std::string line;         // línea del archivo
    int count = 0;            // contador de apariciones

    // pedir palabra a contar al usuario
    std::cout << "Introduzca la palabra a contar: ";
    std::cin >> wordToCount;

    // abrir el archivo para leer
    std::ifstream file("archivo.txt"); // reemplazar "archivo.txt" por el nombre del archivo que deseas leer

    if (!file.is_open()) {
        std::cerr << "Error al abrir el archivo." << std::endl;
        return 1;
    }

    // leer línea por línea y contar apariciones
    while (getline(file, line)) {
        std::transform(line.begin(), line.end(), line.begin(), ::tolower); // convertir a minúsculas para contar palabras iguales
        size_t pos = line.find(wordToCount);
        while (pos != std::string::npos) {
            count++;
            pos = line.find(wordToCount, pos + 1); // buscar la siguiente aparición
        }
    }

    // cerrar el archivo
    file.close();

    // imprimir resultado
    std::cout << "La palabra \"" << wordToCount << "\" aparece " << count << " veces en el archivo." << std::endl;

    return 0;
}
```

En este ejemplo, se pide al usuario que introduzca la palabra a contar, se abre el archivo para leer línea por línea y se cuenta el número de apariciones de la palabra especificada. Se convierte todas las líneas a minúsculas para contar palabras iguales, independientemente de su caso. Al final, se muestra el resultado.

